import React, { useState, useRef, useEffect } from 'react';
import DashboardLayout from '../components/DashboardLayout';
import { useAuth } from '../App';

const suggestions = [
  { icon: '🌾', text: 'Best crop for black cotton soil in winter?' },
  { icon: '💧', text: 'How much water does wheat need per week?' },
  { icon: '🐛', text: 'How to treat aphids on cotton plants?' },
  { icon: '💰', text: 'Current MSP for wheat and rice 2024?' },
  { icon: '🌱', text: 'When should I apply urea fertilizer?' },
  { icon: '🌦️', text: 'How to protect crops from heavy rain?' },
  { icon: '♻️', text: 'Which crops improve soil health?' },
  { icon: '🏛️', text: 'PM-KISAN scheme eligibility and benefits?' },
];

const RESPONSES = {
  wheat: "🌾 **Wheat Farming Guide:**\n\n• Best sowing: November 1–25\n• Seed rate: 100–125 kg/acre\n• First irrigation: 20–25 days after sowing\n• Apply 50kg Urea + 25kg DAP at sowing\n• Expected yield: 18–22 quintals/acre\n• MSP 2024–25: ₹2,275/quintal\n\nWould you like a detailed week-by-week schedule?",
  water: "💧 **Wheat Water Requirements:**\n\n• Total irrigations: 4–6 times\n• Critical stages:\n  - Crown root (21 days)\n  - Tillering (45 days)\n  - Jointing (65 days)\n  - Flowering (85 days)\n• Avoid waterlogging — ensure drainage\n• Drip irrigation saves 40% water",
  aphid: "🐛 **Aphid Control on Cotton:**\n\n• Spray Imidacloprid 17.8 SL @ 0.3ml/liter\n• Or Thiamethoxam 25 WG @ 0.2g/liter\n• Spray in early morning or evening\n• Repeat after 10–15 days if needed\n• Encourage natural predators (ladybirds)\n• Avoid broad-spectrum pesticides",
  msp: "💰 **MSP 2024–25 (Rabi Crops):**\n\n• Wheat: ₹2,275/quintal\n• Barley: ₹1,735/quintal\n• Gram: ₹5,440/quintal\n• Lentil: ₹6,425/quintal\n• Mustard: ₹5,650/quintal\n\nSell at APMC mandi or PM-AASHA scheme for guaranteed MSP.",
  urea: "🧪 **Urea Application Guide:**\n\n• Wheat: 50kg/acre at sowing + 25kg at 21 days\n• Rice: 60kg/acre split in 3 doses\n• Apply in moist soil for best absorption\n• Avoid application before heavy rain\n• Use neem-coated urea for slow release\n• Store in dry, cool place",
  rain: "🌧️ **Crop Protection from Heavy Rain:**\n\n• Ensure proper field drainage channels\n• Apply preventive fungicide (Mancozeb)\n• Avoid irrigation 3 days before rain\n• Harvest ripe crops before storm\n• Stake tall crops to prevent lodging\n• Monitor for waterlogging signs",
  soil: "♻️ **Soil Health Improvement:**\n\n• Practice crop rotation (wheat → legume)\n• Add FYM/compost: 5 tonnes/acre\n• Grow green manure crops (Dhaincha)\n• Reduce tillage to preserve microbiome\n• Test soil every 2 years\n• Target organic matter: 3%+",
  scheme: "🏛️ **PM-KISAN Scheme:**\n\n• Benefit: ₹6,000/year in 3 installments\n• Eligibility: All small & marginal farmers\n• Apply at: pmkisan.gov.in\n• Documents: Aadhaar, land records, bank account\n\n**Other Schemes:**\n• PM Fasal Bima Yojana (crop insurance)\n• Kisan Credit Card (low-interest loans)\n• Soil Health Card scheme",
  default: "🤖 Namaste! I'm KisanGPT, your AI farming assistant!\n\nI can help you with:\n• 🌱 Crop recommendations & sowing tips\n• 🔬 Disease identification & treatment\n• 💧 Irrigation & water management\n• 💰 Market prices & MSP information\n• 🏛️ Government schemes & subsidies\n• 🧪 Fertilizer guidance\n\nAsk me anything in Hindi, Marathi, or English!",
};

function getResponse(msg) {
  const m = msg.toLowerCase();
  if (m.includes('wheat') || m.includes('गेहूं') || m.includes('गहू')) return RESPONSES.wheat;
  if (m.includes('water') || m.includes('irrigation') || m.includes('पानी') || m.includes('सिंचाई')) return RESPONSES.water;
  if (m.includes('aphid') || m.includes('pest') || m.includes('कीट') || m.includes('treat')) return RESPONSES.aphid;
  if (m.includes('msp') || m.includes('price') || m.includes('market') || m.includes('भाव')) return RESPONSES.msp;
  if (m.includes('urea') || m.includes('fertilizer') || m.includes('खाद')) return RESPONSES.urea;
  if (m.includes('rain') || m.includes('बारिश') || m.includes('पाऊस')) return RESPONSES.rain;
  if (m.includes('soil') || m.includes('मिट्टी') || m.includes('माती') || m.includes('eco') || m.includes('health')) return RESPONSES.soil;
  if (m.includes('scheme') || m.includes('kisan') || m.includes('yojana') || m.includes('योजना')) return RESPONSES.scheme;
  return RESPONSES.default;
}

function Message({ msg }) {
  const isBot = msg.role === 'bot';
  return (
    <div className={`flex gap-3 ${isBot ? '' : 'flex-row-reverse'} animate-slide-up`}>
      <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm flex-shrink-0 ${isBot ? 'bg-gradient-to-br from-green-600 to-green-800 ai-glow' : 'bg-gradient-to-br from-gray-600 to-gray-800'}`}>
        {isBot ? '🤖' : '👤'}
      </div>
      <div className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm leading-relaxed ${isBot ? 'glass-green border border-green-700/30 text-gray-200' : 'bg-green-600/80 text-white'}`}>
        {msg.text.split('\n').map((line, i) => (
          <span key={i}>{line.replace(/\*\*(.*?)\*\*/g, '$1')}{i < msg.text.split('\n').length - 1 && <br />}</span>
        ))}
        <div className={`text-xs mt-1.5 ${isBot ? 'text-gray-500' : 'text-green-200'}`}>{msg.time}</div>
      </div>
    </div>
  );
}

export default function ChatbotPage() {
  const { lang } = useAuth();
  const [messages, setMessages] = useState([{ role: 'bot', text: RESPONSES.default, time: 'Now' }]);
  const [input, setInput] = useState('');
  const [typing, setTyping] = useState(false);
  const [listening, setListening] = useState(false);
  const [voiceSupported] = useState(() => 'webkitSpeechRecognition' in window || 'SpeechRecognition' in window);
  const bottomRef = useRef();
  const recognitionRef = useRef(null);

  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [messages, typing]);

  const send = (text) => {
    if (!text.trim()) return;
    const time = new Date().toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' });
    setMessages(m => [...m, { role: 'user', text, time }]);
    setInput('');
    setTyping(true);
    setTimeout(() => {
      setTyping(false);
      setMessages(m => [...m, { role: 'bot', text: getResponse(text), time: new Date().toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' }) }]);
    }, 1000 + Math.random() * 800);
  };

  const toggleVoice = () => {
    if (!voiceSupported) return;
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (listening) {
      recognitionRef.current?.stop();
      setListening(false);
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = lang === 'hi' ? 'hi-IN' : lang === 'mr' ? 'mr-IN' : 'en-IN';
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.onresult = (e) => { setInput(e.results[0][0].transcript); setListening(false); };
    recognition.onerror = () => setListening(false);
    recognition.onend = () => setListening(false);
    recognitionRef.current = recognition;
    recognition.start();
    setListening(true);
  };

  return (
    <DashboardLayout title="KisanGPT Voice Assistant" subtitle="AI farming assistant — speak or type in your language">
      <div className="flex flex-col lg:flex-row gap-5 h-[calc(100vh-180px)]">

        {/* Sidebar */}
        <div className="lg:w-60 flex-shrink-0 space-y-4">
          <div className="glass rounded-2xl p-4 border border-green-900/30">
            <div className="flex items-center gap-2 mb-2">
              <div className="w-2 h-2 rounded-full bg-green-400 animate-pulse" />
              <span className="text-green-400 text-xs font-semibold uppercase tracking-wider">AI Online</span>
            </div>
            <div className="text-white font-semibold text-sm mb-1">KisanGPT</div>
            <div className="text-gray-400 text-xs mb-3">Trained on 10M+ farming data points. Supports Hindi, Marathi, Punjabi, Telugu & English.</div>
            {voiceSupported && (
              <button onClick={toggleVoice}
                className={`w-full flex items-center justify-center gap-2 py-2.5 rounded-xl text-sm font-semibold transition-all ${listening ? 'bg-red-600/80 text-white voice-ring' : 'glass-green border border-green-700/30 text-green-300 hover:bg-green-900/30'}`}>
                {listening ? <><span className="animate-ping text-lg">🎙️</span> Listening...</> : <><span>🎙️</span> Speak Now</>}
              </button>
            )}
          </div>

          <div className="glass rounded-2xl p-4 border border-green-900/30">
            <div className="text-gray-400 text-xs uppercase tracking-wider mb-3">Quick Questions</div>
            <div className="space-y-1.5">
              {suggestions.map((s, i) => (
                <button key={i} onClick={() => send(s.text)}
                  className="w-full text-left glass-dark rounded-xl p-2.5 text-xs text-gray-300 hover:text-white hover:bg-green-900/20 transition-all flex items-start gap-2">
                  <span className="flex-shrink-0">{s.icon}</span>
                  <span className="line-clamp-2">{s.text}</span>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Chat Window */}
        <div className="flex-1 flex flex-col glass rounded-2xl border border-green-900/30 overflow-hidden">
          {/* Header */}
          <div className="p-4 border-b border-green-900/30 flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-gradient-to-br from-green-600 to-green-800 flex items-center justify-center text-xl ai-glow">🤖</div>
            <div className="flex-1">
              <div className="text-white font-semibold text-sm">KisanGPT</div>
              <div className="flex items-center gap-1.5">
                <div className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse" />
                <span className="text-green-400 text-xs">Online · Voice + Text</span>
              </div>
            </div>
            <div className="flex gap-2">
              <div className="glass-green px-3 py-1 rounded-full text-green-300 text-xs border border-green-700/30">
                {lang.toUpperCase()}
              </div>
              {listening && (
                <div className="bg-red-600/80 px-3 py-1 rounded-full text-white text-xs flex items-center gap-1">
                  <span className="animate-pulse">●</span> Listening
                </div>
              )}
            </div>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {messages.map((msg, i) => <Message key={i} msg={msg} />)}
            {typing && (
              <div className="flex gap-3 animate-fade-in">
                <div className="w-8 h-8 rounded-full bg-gradient-to-br from-green-600 to-green-800 flex items-center justify-center text-sm ai-glow">🤖</div>
                <div className="glass-green border border-green-700/30 rounded-2xl px-4 py-3 flex items-center gap-1">
                  <div className="w-2 h-2 rounded-full bg-green-400 typing-dot" />
                  <div className="w-2 h-2 rounded-full bg-green-400 typing-dot" />
                  <div className="w-2 h-2 rounded-full bg-green-400 typing-dot" />
                </div>
              </div>
            )}
            <div ref={bottomRef} />
          </div>

          {/* Input */}
          <div className="p-4 border-t border-green-900/30">
            <div className="flex gap-2">
              {voiceSupported && (
                <button onClick={toggleVoice}
                  className={`w-11 h-11 rounded-xl flex items-center justify-center text-lg transition-all flex-shrink-0 ${listening ? 'bg-red-600/80 text-white voice-ring' : 'glass-dark text-gray-400 hover:text-white'}`}>
                  🎙️
                </button>
              )}
              <input value={input} onChange={e => setInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && !e.shiftKey && send(input)}
                placeholder={listening ? 'Listening... speak now' : 'Ask about crops, diseases, weather, schemes...'}
                className="flex-1 bg-black/30 border border-green-900/40 text-white rounded-2xl px-4 py-3 text-sm placeholder-gray-600 transition-all" />
              <button onClick={() => send(input)} disabled={!input.trim() || typing}
                className={`btn-primary text-white px-5 py-3 rounded-2xl font-semibold text-sm flex-shrink-0 ${(!input.trim() || typing) ? 'opacity-50' : ''}`}>
                →
              </button>
            </div>
            <div className="text-gray-600 text-xs text-center mt-2">KisanGPT may make mistakes. Verify critical decisions with local agricultural experts.</div>
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
}
